using System;
using System.Collections.Generic;
using System.Linq;

public record Money(decimal Amount, string Currency)
{
    public static Money IDR(decimal amount) => new(amount, "IDR");
}

public class OrderItem
{
    public string ProductName { get; }
    public int Quantity { get; }
    public decimal Price { get; }

    public OrderItem(string productName, int quantity, decimal price)
    {
        ProductName = productName;
        Quantity = quantity;
        Price = price;
    }
}

public class Order
{
    public Guid Id { get; } = Guid.NewGuid();
    public bool IsFinalized { get; private set; }

    private readonly List<OrderItem> _items = new();
    public IReadOnlyCollection<OrderItem> Items => _items.AsReadOnly();

    public void AddItem(string product, int quantity, decimal price)
    {
        if (IsFinalized)
            throw new InvalidOperationException("Order sudah final! Tidak dapat menambah item.");
        if (quantity <= 0)
            throw new ArgumentException("Quantity harus lebih besar dari 0!");

        _items.Add(new OrderItem(product, quantity, price));
    }

    public void FinalizeOrder()
    {
        if (_items.Count == 0) throw new InvalidOperationException("Order kosong tidak bisa di-finalize!");
        IsFinalized = true;
    }
}

public class Program
{
    public static void Main()
    {
        var order = new Order();
        order.AddItem("Server Rack 42U", 1, 15_000_000);
        order.FinalizeOrder();

        Console.WriteLine($"Order {order.Id} Finalized. Total Item: {order.Items.Count}");

        try
        {
            // Coba tambahkan item setelah finalized (Harus Gagal!)
            order.AddItem("UPS Backup", 1, 3_000_000);
        }
        catch (InvalidOperationException ex)
        {
            Console.WriteLine($"[INVARIANT TERJAGA]: {ex.Message}");
        }
    }
}

